-- KMI Paket B / 0132 PRODUCTION PREFLIGHT — READ-ONLY. Every row with ok must be true; "info" rows are for the record.
select '0132 not recorded and objects absent' chk, not exists (select 1 from supabase_migrations.schema_migrations where name like '0132%') and to_regclass('kmi_next.toolist_attestations') is null and to_regprocedure('kmi_next.toolist_checks(uuid)') is null as ok, '' info
union all select '0106 document control present (document_publish, dc_start_refusal, dc_validity, document_signature_ok, upload_document)', to_regprocedure('kmi_next.document_publish(uuid,text)') is not null and to_regprocedure('kmi_next.dc_start_refusal(uuid,integer)') is not null and to_regprocedure('kmi_next.dc_validity(uuid)') is not null and to_regprocedure('kmi_next.document_signature_ok(text,bytea)') is not null and to_regprocedure('kmi_next.upload_document(text,text,uuid,text,text,text,text,date,text,uuid)') is not null, ''
union all select 'CAM / link tables present', to_regclass('kmi_next.document_op_links') is not null and to_regclass('kmi_next.cam_program_tools') is not null and to_regclass('kmi_next.cam_programs') is not null, ''
union all select '0132 is independent of 0131 / 0133 (no 0131-0133 migration required or recorded is fine)', true, (select coalesce(string_agg(name, ','), 'none recorded') from supabase_migrations.schema_migrations where name like '0131%' or name like '0133%')
union all select '0129 and 0130 recorded (live base)', (select count(*) from supabase_migrations.schema_migrations where name like '0129%' or name like '0130%') >= 2, ''
union all select '0128 pilot postcheck 10/10', (select count(*) filter (where ok) = 10 from kmi_next.pilot_isolation_postcheck()), ''
union all select 'upload_document has NO spreadsheet MIME today (root cause of MIME_NOT_ALLOWED)', position('spreadsheetml' in pg_get_functiondef('kmi_next.upload_document(text,text,uuid,text,text,text,text,date,text,uuid)'::regprocedure)) = 0, ''
union all select 'storage buckets accept any MIME (the block is in upload_document, not in storage)', not exists (select 1 from storage.buckets where allowed_mime_types is not null), (select string_agg(id, ',') from storage.buckets)
union all select 'info: START GATE impact — open work-order operations that carry a CAM program (these would need an EFFECTIVE tool list to start)', true, (select count(*)::text from kmi_next.work_order_operations x join kmi_next.work_orders w on w.id = x.work_order_id where x.cam_program_id is not null and w.status not in ('COMPLETED','CANCELLED','CLOSED','SHIPPED','PRODUCTION_DONE'))
union all select 'info: active work orders now', true, (select count(*)::text from kmi_next.work_orders where status in ('IN_PROGRESS','FIRST_PIECE_PENDING','FIRST_PIECE_APPROVED'))
union all select 'info: TOOL_LIST documents / effective', true, (select count(*)::text from kmi_next.documents where doc_type = 'TOOL_LIST') || ' / ' || (select count(*)::text from kmi_next.documents d join kmi_next.document_controls c on c.document_id = d.id where d.doc_type = 'TOOL_LIST' and c.state = 'EFFECTIVE')
union all select 'info: documents / versions row counts (must be identical after apply)', true, (select count(*)::text from kmi_next.documents) || ' / ' || (select count(*)::text from kmi_next.document_versions);
